import React, { useState } from "react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";

export default function ExcelFilter() {
  const [excelData, setExcelData] = useState([]);

  const [startDate, setStartDate] = useState("");

  const [endDate, setEndDate] = useState("");

  const [employeeInput, setEmployeeInput] = useState("");

  const [results, setResults] = useState([]);

  // Convert Excel Date
  const parseDate = (value) => {
    if (!value) return null;

    // Excel number date
    if (typeof value === "number") {
      const excelDate = XLSX.SSF.parse_date_code(value);

      return new Date(excelDate.y, excelDate.m - 1, excelDate.d);
    }

    // String date
    if (typeof value === "string") {
      const onlyDate = value.split(" ")[0];

      const parts = onlyDate.split("/");

      if (parts.length !== 3) return null;

      return new Date(parts[2], parts[1] - 1, parts[0]);
    }

    return null;
  };

  // Upload Excel
  const handleFileUpload = (e) => {
    const file = e.target.files[0];

    if (!file) return;

    const reader = new FileReader();

    reader.onload = (evt) => {
      const data = evt.target.result;

      const workbook = XLSX.read(data, {
        type: "binary",
      });

      // Sheet name
      const sheetName = "BP.DVKH gửi nội dung Phản ánh";

      const worksheet = workbook.Sheets[sheetName];

      if (!worksheet) {
        alert("Không tìm thấy sheet!");

        return;
      }

      // Read JSON
      const jsonData = XLSX.utils.sheet_to_json(worksheet, {
        raw: false,
        defval: "",
      });

      console.log(jsonData);

      setExcelData(jsonData);

      alert("Đọc file Excel thành công!");
    };

    reader.readAsBinaryString(file);
  };

  // Filter
  const handleFilter = () => {
    if (!startDate || !endDate) {
      alert("Vui lòng chọn ngày!");

      return;
    }

    const start = new Date(startDate);

    const end = new Date(endDate);

    // Input -> Array
    const employeeArray = employeeInput
      .split(",")
      .map((item) => item.trim().toLowerCase())
      .filter(Boolean);

    const filtered = excelData.filter((row) => {
      // Find employee key
      const employeeKey = Object.keys(row).find((key) =>
        key.includes("Tên nhân viên QLCL-DV"),
      );

      // Find date key
      const dateKey = Object.keys(row).find((key) =>
        key.includes("Ngày phản hồi"),
      );

      // Parse excel date
      const excelDate = parseDate(row[dateKey]);

      // Employee value
      const employeeValue =
        row[employeeKey]?.toString().trim().toLowerCase() || "";

      // Compare date
      const isDateMatch = excelDate >= start && excelDate <= end;

      // Compare employee
      const isEmployeeMatch = employeeArray.includes(employeeValue);

      return isDateMatch && isEmployeeMatch;
    });

    console.log(filtered);

    setResults(filtered);

    if (filtered.length === 0) {
      alert("Không tìm thấy dữ liệu!");
    }
  };

  // Export Excel
  const handleExportExcel = () => {
    if (results.length === 0) {
      alert("Không có dữ liệu để export!");

      return;
    }

    const exportData = results.map((row, index) => ({
      STT: index + 1,

      "Ngày phản hồi": row["Ngày phản hồi"],

      "Tên nhân viên QLCL-DV": row["Tên nhân viên QLCL-DV"],

      "Nội dung tiếp nhận Phản ánh": row["Nội dung tiếp nhận Phản ánh"],
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);

    // Auto width
    worksheet["!cols"] = [{ wch: 10 }, { wch: 20 }, { wch: 30 }, { wch: 100 }];

    const workbook = XLSX.utils.book_new();

    XLSX.utils.book_append_sheet(workbook, worksheet, "KetQua");

    const excelBuffer = XLSX.write(workbook, {
      bookType: "xlsx",
      type: "array",
    });

    const data = new Blob([excelBuffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8",
    });

    saveAs(data, `KetQuaLoc_${Date.now()}.xlsx`);
  };

  return (
    <div
      style={{
        padding: 30,
        fontFamily: "Arial",
      }}
    >
      <h1>Tra cứu phản ánh</h1>

      {/* Upload */}
      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Upload File Excel</label>

        <br />

        <input type="file" accept=".xlsx,.xls" onChange={handleFileUpload} />
      </div>

      {/* Start date */}
      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Ngày bắt đầu</label>

        <br />

        <input
          type="date"
          value={startDate}
          onChange={(e) => setStartDate(e.target.value)}
        />
      </div>

      {/* End date */}
      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Ngày kết thúc</label>

        <br />

        <input
          type="date"
          value={endDate}
          onChange={(e) => setEndDate(e.target.value)}
        />
      </div>

      {/* Employee */}
      <div
        style={{
          marginBottom: 20,
        }}
      >
        <label>Tên nhân viên QLCL-DV</label>

        <br />

        <input
          type="text"
          placeholder="VD: Nguyễn Văn A, Trần Thị B"
          value={employeeInput}
          onChange={(e) => setEmployeeInput(e.target.value)}
          style={{
            width: 500,
            padding: 10,
          }}
        />

        <p
          style={{
            color: "#666",
          }}
        >
          Nhập nhiều tên bằng dấu phẩy (,)
        </p>
      </div>

      {/* Buttons */}
      <div
        style={{
          marginBottom: 30,
        }}
      >
        <button
          onClick={handleFilter}
          style={{
            padding: "10px 20px",
            cursor: "pointer",
          }}
        >
          Tìm kiếm
        </button>

        <button
          onClick={handleExportExcel}
          style={{
            padding: "10px 20px",
            marginLeft: 10,
            cursor: "pointer",
          }}
        >
          Export Excel
        </button>
      </div>

      {/* Result */}
      <table
        border="1"
        cellPadding="10"
        style={{
          borderCollapse: "collapse",
          width: "100%",
        }}
      >
        <thead>
          <tr>
            <th>STT</th>

            <th>Ngày phản hồi</th>

            <th>Tên nhân viên QLCL-DV</th>

            <th>Nội dung tiếp nhận Phản ánh</th>
          </tr>
        </thead>

        <tbody>
          {results.map((row, index) => (
            <tr key={index}>
              <td>{index + 1}</td>

              <td>{row["Ngày phản hồi"]}</td>

              <td>{row["Tên nhân viên QLCL-DV"]}</td>

              <td>{row["Nội dung tiếp nhận Phản ánh"]}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
